package main

import (
	"fmt"
	"sync"
	"sync/atomic"
)

// Config 是不可变配置，换配置时整体替换指针
type Config struct {
	Addr string
}

var (
	configOnce sync.Once
	configPtr  atomic.Pointer[Config]
	hits       atomic.Int64
	ready      atomic.Bool
	statsMu    sync.Mutex
	stats      = map[string]int{}
)

func loadConfig() *Config {
	return &Config{Addr: "127.0.0.1:8080"}
}

func handle(name string) {
	hits.Add(1)
	statsMu.Lock()
	stats[name]++
	statsMu.Unlock()
}

func main() {
	// 1. Once 初始化，再用 atomic.Pointer 发布出去
	configOnce.Do(func() {
		configPtr.Store(loadConfig())
	})
	ready.Store(true)

	// 2. 并发处理请求：atomic 计数，Mutex 保护 map
	var wg sync.WaitGroup
	for _, name := range []string{"login", "login", "pay", "query"} {
		wg.Add(1)
		go func(name string) {
			defer wg.Done()
			handle(name)
		}(name)
	}
	wg.Wait()

	fmt.Println("配置:", configPtr.Load().Addr, "就绪:", ready.Load())
	fmt.Println("总请求:", hits.Load())
	fmt.Println("登录次数:", stats["login"])

	// 3. 换配置：整体替换指针，读的一方不用加锁
	next := &Config{Addr: "127.0.0.1:9090"}
	old := configPtr.Swap(next)
	fmt.Println("旧配置:", old.Addr, "新配置:", configPtr.Load().Addr)
}
